-- Independent meeting-turn accounting and shared daily budget enforcement.
-- This migration makes no provider call and creates no execution worker.
begin;
create table bizoveya_private.meeting_turn_runs(
 id uuid primary key,snapshot_id uuid not null references bizoveya_private.meeting_execution_snapshots(id) on delete cascade,
 consent_id uuid not null references bizoveya_private.meeting_execution_consents(id),ordinal smallint not null check(ordinal between 1 and 6),
 profile_id uuid not null references bizoveya_private.model_profiles(id),profile_version integer not null,policy_version integer not null,policy_snapshot jsonb not null,
 claim uuid not null,actor_id uuid not null,status text not null check(status in('reserved','succeeded','failed')),
 spending_state text not null check(spending_state in('reserved','settled','unknown','overrun','reconciled')),
 reserved_micros bigint not null check(reserved_micros>=0),charged_micros bigint not null check(charged_micros>=0),
 input_token_limit integer not null check(input_token_limit>0),output_token_limit integer not null check(output_token_limit>0),
 input_tokens integer,output_tokens integer,error_code text,provider_started_at timestamptz,created_at timestamptz not null default clock_timestamp(),finished_at timestamptz,
 unique(snapshot_id,ordinal),
 check((status='reserved' and finished_at is null and error_code is null) or status<>'reserved')
);
create index meeting_turn_profile_created_idx on bizoveya_private.meeting_turn_runs(profile_id,created_at desc);
create table bizoveya_private.meeting_turn_spending_events(
 id uuid primary key default gen_random_uuid(),turn_id uuid not null references bizoveya_private.meeting_turn_runs(id) on delete cascade,
 action text not null check(action in('reserved','provider_started','settled','unknown','overrun','reconciled')),
 amount_micros bigint not null check(amount_micros>=0),actor_id uuid,reason text not null,occurred_at timestamptz not null default clock_timestamp()
);
alter table bizoveya_private.meeting_turn_runs enable row level security;
alter table bizoveya_private.meeting_turn_spending_events enable row level security;
revoke all on bizoveya_private.meeting_turn_runs,bizoveya_private.meeting_turn_spending_events from public,anon,authenticated,service_role;

-- Preparation and consent must see unresolved meeting accounting too.
alter function bizoveya_private.deliberation_execution_candidate(uuid,uuid,uuid,uuid,integer,integer) rename to deliberation_candidate_before_meeting_accounting;
create function bizoveya_private.deliberation_execution_candidate(p_workspace_id uuid,p_site_id uuid,p_meeting_id uuid,p_plan_id uuid,p_meeting_version integer,p_schedule_version integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare candidate_ jsonb;begin
 candidate_:=bizoveya_private.deliberation_candidate_before_meeting_accounting(p_workspace_id,p_site_id,p_meeting_id,p_plan_id,p_meeting_version,p_schedule_version);
 if exists(select 1 from jsonb_array_elements(candidate_->'snapshot'->'turns') t where exists(select 1 from bizoveya_private.meeting_turn_runs m where m.profile_id=(t->>'profileId')::uuid and (m.spending_state in('unknown','overrun') or m.spending_state='reserved' and m.created_at<statement_timestamp()-interval '90 seconds'))) then raise exception 'bz_spending_unresolved';end if;
 return candidate_;
end;$$;

create function public.bz_begin_meeting_turn(p_snapshot_id uuid,p_consent_id uuid,p_turn_id uuid,p_ordinal integer,p_claim uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare x bizoveya_private.meeting_execution_snapshots%rowtype;c bizoveya_private.meeting_execution_consents%rowtype;p bizoveya_private.meeting_deliberation_plans%rowtype;a bizoveya_private.agency_records%rowtype;s bizoveya_private.meeting_deliberation_schedules%rowtype;r bizoveya_private.site_agent_rosters%rowtype;
 t jsonb;b bizoveya_private.agent_model_bindings%rowtype;sp bizoveya_private.spending_policies%rowtype;pv bizoveya_private.model_profile_versions%rowtype;existing bizoveya_private.meeting_turn_runs%rowtype;amount_ bigint;spent_ bigint;workspace_ uuid;
begin
 if p_snapshot_id is null or p_consent_id is null or p_turn_id is null or p_claim is null or p_actor_id is null or p_ordinal is null or p_ordinal not between 1 and 6 then raise exception 'bz_invalid_meeting_turn';end if;
 perform pg_advisory_xact_lock(817030);
 select * into existing from bizoveya_private.meeting_turn_runs where id=p_turn_id;
 if existing.id is not null then
  if existing.snapshot_id=p_snapshot_id and existing.consent_id=p_consent_id and existing.ordinal=p_ordinal and existing.claim=p_claim and existing.actor_id=p_actor_id then return jsonb_build_object('id',existing.id,'snapshotId',existing.snapshot_id,'ordinal',existing.ordinal,'status',existing.status,'spendingState',existing.spending_state,'reservedMicros',existing.reserved_micros,'execute',false);end if;
  raise exception 'bz_conflict';
 end if;
 select * into x from bizoveya_private.meeting_execution_snapshots where id=p_snapshot_id;
 select * into c from bizoveya_private.meeting_execution_consents where id=p_consent_id;
 select * into p from bizoveya_private.meeting_deliberation_plans where id=x.plan_id;
 select * into a from bizoveya_private.agency_records where id=p.meeting_id for update;
 select * into s from bizoveya_private.meeting_deliberation_schedules where plan_id=p.id for update;
 select * into r from bizoveya_private.site_agent_rosters where site_id=a.site_id for share;
 select workspace_id into workspace_ from public.bizoveya_sites where id=a.site_id for update;
 if x.id is null or c.id is null or c.snapshot_id<>x.id or c.actor_id<>p_actor_id or x.actor_id<>p_actor_id or c.revoked_at is not null or c.expires_at<=statement_timestamp() then raise exception 'bz_meeting_consent_required';end if;
 if not exists(select 1 from bizoveya_private.platform_admins where user_id=p_actor_id) or not exists(select 1 from public.bizoveya_memberships where workspace_id=workspace_ and user_id=p_actor_id and role='owner') then raise exception 'bz_forbidden';end if;
 if a.status<>'decision-recorded' or a.version<>(x.summary->>'meetingVersion')::integer or s.state<>'ready' or s.version<>(x.summary->>'scheduleVersion')::integer then raise exception 'bz_meeting_snapshot_not_ready';end if;
 if r.document->'enabled' is distinct from 'true'::jsonb or r.version<>(x.summary->>'rosterVersion')::integer then raise exception 'bz_site_roster_changed';end if;
 if coalesce((select version from public.bizoveya_site_agent_preferences where site_id=a.site_id),0)<>(x.input_snapshot->'preferences'->>'version')::integer then raise exception 'bz_meeting_snapshot_changed';end if;
 if exists(select 1 from jsonb_array_elements(x.input_snapshot->'knowledge') k where not exists(select 1 from public.bizoveya_knowledge_sources q where q.id=(k->>'sourceId')::uuid and q.site_id=a.site_id and q.approved and q.version=(k->>'sourceVersion')::integer)) then raise exception 'bz_meeting_snapshot_changed';end if;
 select value into t from jsonb_array_elements(x.input_snapshot->'turns') where (value->>'ordinal')::integer=p_ordinal;
 if t is null then raise exception 'bz_invalid_meeting_turn';end if;
 select * into b from bizoveya_private.agent_model_bindings where agent_id=(t->>'agentId')::uuid for share;
 select * into sp from bizoveya_private.spending_policies where profile_id=(t->>'profileId')::uuid for share;
 select * into pv from bizoveya_private.model_profile_versions where profile_id=(t->>'profileId')::uuid and version=(t->>'profileVersion')::integer;
 if b.agent_id is null or b.revision<>(t->>'bindingRevision')::integer or bizoveya_private.binding_issue(b) is not null or sp.version<>(t->>'spendingPolicyVersion')::integer or sp.document is distinct from t->'spendingPolicy' or sp.document->'enabled' is distinct from 'true'::jsonb or (sp.document->>'validUntil')::timestamptz<=statement_timestamp() then raise exception 'bz_meeting_snapshot_changed';end if;
 if exists(select 1 from bizoveya_private.spending_ledger l where l.profile_id=b.profile_id and (l.state in('unknown','overrun') or l.state='reserved' and l.started_at<statement_timestamp()-interval '90 seconds')) or exists(select 1 from bizoveya_private.generation_stage_runs g where g.profile_id=b.profile_id and (g.spending_state in('unknown','overrun') or g.spending_state='reserved' and g.created_at<statement_timestamp()-interval '90 seconds')) or exists(select 1 from bizoveya_private.meeting_turn_runs m where m.profile_id=b.profile_id and (m.spending_state in('unknown','overrun') or m.spending_state='reserved' and m.created_at<statement_timestamp()-interval '90 seconds')) then raise exception 'bz_spending_unresolved';end if;
 if p_ordinal>1 and not exists(select 1 from bizoveya_private.meeting_turn_runs prior where prior.snapshot_id=x.id and prior.ordinal=p_ordinal-1 and prior.status='succeeded' and prior.spending_state in('settled','reconciled')) then raise exception 'bz_meeting_turn_order';end if;
 amount_:=(t->>'estimatedCeilingMicros')::bigint;
 if amount_>(sp.document->>'runLimitMicros')::bigint then raise exception 'bz_run_budget';end if;
 select coalesce((select sum(charged_micros) from bizoveya_private.spending_ledger where profile_id=b.profile_id and started_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)+coalesce((select sum(charged_micros) from bizoveya_private.generation_stage_runs where profile_id=b.profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)+coalesce((select sum(charged_micros) from bizoveya_private.meeting_turn_runs where profile_id=b.profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0) into spent_;
 if spent_+amount_>least((sp.document->>'dailyLimitMicros')::bigint,(pv.document->>'dailyBudgetCents')::bigint*10000) then raise exception 'bz_daily_budget';end if;
 if coalesce((select sum(charged_micros) from bizoveya_private.meeting_turn_runs where snapshot_id=x.id),0)+amount_>(x.summary->>'maxTotalCostMicros')::bigint then raise exception 'bz_meeting_cost_ceiling';end if;
 insert into bizoveya_private.meeting_turn_runs(id,snapshot_id,consent_id,ordinal,profile_id,profile_version,policy_version,policy_snapshot,claim,actor_id,status,spending_state,reserved_micros,charged_micros,input_token_limit,output_token_limit)
 values(p_turn_id,x.id,c.id,p_ordinal,b.profile_id,b.profile_version,sp.version,sp.document,p_claim,p_actor_id,'reserved','reserved',amount_,amount_,(x.summary->>'maxInputTokensPerTurn')::integer,(x.summary->>'maxOutputTokensPerTurn')::integer);
 insert into bizoveya_private.meeting_turn_spending_events(turn_id,action,amount_micros,actor_id,reason) values(p_turn_id,'reserved',amount_,p_actor_id,'Reserved meeting turn before any provider request');
 return jsonb_build_object('id',p_turn_id,'snapshotId',x.id,'ordinal',p_ordinal,'status','reserved','spendingState','reserved','reservedMicros',amount_,'execute',false);
exception when unique_violation then raise exception 'bz_conflict';end;$$;

create function public.bz_record_meeting_turn_provider_start(p_turn_id uuid,p_claim uuid) returns void language plpgsql security definer set search_path='' as $$
declare m bizoveya_private.meeting_turn_runs%rowtype;c bizoveya_private.meeting_execution_consents%rowtype;x bizoveya_private.meeting_execution_snapshots%rowtype;p bizoveya_private.meeting_deliberation_plans%rowtype;a bizoveya_private.agency_records%rowtype;s bizoveya_private.meeting_deliberation_schedules%rowtype;r bizoveya_private.site_agent_rosters%rowtype;workspace_ uuid;begin
 perform pg_advisory_xact_lock(817030);select * into m from bizoveya_private.meeting_turn_runs where id=p_turn_id for update;select * into c from bizoveya_private.meeting_execution_consents where id=m.consent_id;select * into x from bizoveya_private.meeting_execution_snapshots where id=m.snapshot_id;select * into p from bizoveya_private.meeting_deliberation_plans where id=x.plan_id;select * into a from bizoveya_private.agency_records where id=p.meeting_id for update;select * into s from bizoveya_private.meeting_deliberation_schedules where plan_id=p.id for update;select * into r from bizoveya_private.site_agent_rosters where site_id=a.site_id for share;select workspace_id into workspace_ from public.bizoveya_sites where id=a.site_id for update;
 if m.id is null or m.claim is distinct from p_claim or m.status<>'reserved' or m.provider_started_at is not null then raise exception 'bz_conflict';end if;
 if c.revoked_at is not null or c.expires_at<=statement_timestamp() then raise exception 'bz_meeting_consent_required';end if;
 if not exists(select 1 from bizoveya_private.platform_admins where user_id=m.actor_id) or not exists(select 1 from public.bizoveya_memberships where workspace_id=workspace_ and user_id=m.actor_id and role='owner') then raise exception 'bz_forbidden';end if;
 if a.status<>'decision-recorded' or a.version<>(x.summary->>'meetingVersion')::integer or s.state<>'ready' or s.version<>(x.summary->>'scheduleVersion')::integer then raise exception 'bz_meeting_snapshot_not_ready';end if;
 if r.document->'enabled' is distinct from 'true'::jsonb or r.version<>(x.summary->>'rosterVersion')::integer or not exists(select 1 from bizoveya_private.spending_policies sp where sp.profile_id=m.profile_id and sp.version=m.policy_version and sp.document=m.policy_snapshot and sp.document->'enabled'='true'::jsonb and (sp.document->>'validUntil')::timestamptz>statement_timestamp()) then raise exception 'bz_meeting_snapshot_changed';end if;
 update bizoveya_private.meeting_turn_runs set provider_started_at=clock_timestamp() where id=m.id;
 insert into bizoveya_private.meeting_turn_spending_events(turn_id,action,amount_micros,reason) values(m.id,'provider_started',m.reserved_micros,'Server marker immediately before a future provider request');
end;$$;
create function public.bz_cancel_unstarted_meeting_turn(p_turn_id uuid,p_claim uuid) returns void language plpgsql security definer set search_path='' as $$
declare m bizoveya_private.meeting_turn_runs%rowtype;begin perform pg_advisory_xact_lock(817030);select * into m from bizoveya_private.meeting_turn_runs where id=p_turn_id for update;
 if m.id is null or m.claim is distinct from p_claim then raise exception 'bz_conflict';end if;if m.status<>'reserved' then return;end if;if m.provider_started_at is not null then raise exception 'bz_provider_already_started';end if;
 update bizoveya_private.meeting_turn_runs set status='failed',spending_state='settled',charged_micros=0,input_tokens=0,output_tokens=0,error_code='preflight_failed',finished_at=clock_timestamp() where id=m.id;
 insert into bizoveya_private.meeting_turn_spending_events(turn_id,action,amount_micros,reason) values(m.id,'settled',0,'Cancelled before any provider request');end;$$;
create function public.bz_finish_meeting_turn_spending(p_turn_id uuid,p_claim uuid,p_succeeded boolean,p_error_code text,p_input_tokens integer,p_output_tokens integer) returns void language plpgsql security definer set search_path='' as $$
declare m bizoveya_private.meeting_turn_runs%rowtype;cost_ bigint;state_ text;begin perform pg_advisory_xact_lock(817030);select * into m from bizoveya_private.meeting_turn_runs where id=p_turn_id for update;
 if m.id is null or m.claim is distinct from p_claim then raise exception 'bz_conflict';end if;if m.status<>'reserved' then return;end if;if m.provider_started_at is null then raise exception 'bz_provider_not_started';end if;
 if p_input_tokens is null or p_output_tokens is null then cost_:=m.reserved_micros;state_:='unknown';elsif p_input_tokens<0 or p_output_tokens<0 then raise exception 'bz_invalid_meeting_turn';else cost_:=ceil((p_input_tokens::numeric*(m.policy_snapshot->>'inputRateMicros')::numeric+p_output_tokens::numeric*(m.policy_snapshot->>'outputRateMicros')::numeric)/1000000+(m.policy_snapshot->>'requestFeeMicros')::numeric);state_:=case when cost_>m.reserved_micros or p_input_tokens>m.input_token_limit or p_output_tokens>m.output_token_limit then 'overrun' else 'settled' end;end if;
 update bizoveya_private.meeting_turn_runs set status=case when p_succeeded and state_='settled' then 'succeeded' else 'failed' end,spending_state=state_,charged_micros=cost_,input_tokens=p_input_tokens,output_tokens=p_output_tokens,error_code=case when p_succeeded and state_='settled' then null else coalesce(left(p_error_code,120),state_) end,finished_at=clock_timestamp() where id=m.id;
 insert into bizoveya_private.meeting_turn_spending_events(turn_id,action,amount_micros,reason) values(m.id,state_,cost_,'Server-recorded meeting usage; USD estimate from captured pricing');end;$$;

-- Fresh connectivity and campaign reservations include meeting charges and blockers.
alter function public.bz_admin_begin_model_test(uuid,uuid,integer,integer,uuid,boolean,text) set schema bizoveya_private;
alter function bizoveya_private.bz_admin_begin_model_test(uuid,uuid,integer,integer,uuid,boolean,text) rename to begin_model_test_before_meeting_budget;
create function public.bz_admin_begin_model_test(p_id uuid,p_profile_id uuid,p_expected_revision integer,p_expected_credential_version integer,p_claim uuid,p_reviewed boolean,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$
declare result_ jsonb;policy_ bizoveya_private.spending_policies%rowtype;profile_ bizoveya_private.model_profiles%rowtype;limit_ bigint;begin perform pg_advisory_xact_lock(817030);
 if exists(select 1 from bizoveya_private.model_test_runs where id=p_id) then return bizoveya_private.begin_model_test_before_meeting_budget(p_id,p_profile_id,p_expected_revision,p_expected_credential_version,p_claim,p_reviewed,p_reason);end if;
 if exists(select 1 from bizoveya_private.meeting_turn_runs where profile_id=p_profile_id and (spending_state in('unknown','overrun') or spending_state='reserved' and created_at<statement_timestamp()-interval '90 seconds')) then raise exception 'bz_spending_unresolved';end if;
 result_:=bizoveya_private.begin_model_test_before_meeting_budget(p_id,p_profile_id,p_expected_revision,p_expected_credential_version,p_claim,p_reviewed,p_reason);
 select * into policy_ from bizoveya_private.spending_policies where profile_id=p_profile_id;select * into profile_ from bizoveya_private.model_profiles where id=p_profile_id;limit_:=least((policy_.document->>'dailyLimitMicros')::bigint,(select (document->>'dailyBudgetCents')::bigint*10000 from bizoveya_private.model_profile_versions where profile_id=profile_.id and version=profile_.version));
 if (select coalesce(sum(charged_micros),0) from bizoveya_private.spending_ledger where profile_id=p_profile_id and started_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC')+coalesce((select sum(charged_micros) from bizoveya_private.generation_stage_runs where profile_id=p_profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)+coalesce((select sum(charged_micros) from bizoveya_private.meeting_turn_runs where profile_id=p_profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)>limit_ then raise exception 'bz_daily_budget';end if;return result_;end;$$;
alter function public.bz_begin_campaign_generation_stage(uuid,uuid,text,uuid,uuid) set schema bizoveya_private;
alter function bizoveya_private.bz_begin_campaign_generation_stage(uuid,uuid,text,uuid,uuid) rename to begin_generation_before_meeting_budget;
create function public.bz_begin_campaign_generation_stage(p_generation_id uuid,p_stage_id uuid,p_kind text,p_claim uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare result_ jsonb;g bizoveya_private.generation_stage_runs%rowtype;limit_ bigint;begin perform pg_advisory_xact_lock(817030);
 select * into g from bizoveya_private.generation_stage_runs where id=p_stage_id;if g.id is not null then return bizoveya_private.begin_generation_before_meeting_budget(p_generation_id,p_stage_id,p_kind,p_claim,p_actor_id);end if;
 result_:=bizoveya_private.begin_generation_before_meeting_budget(p_generation_id,p_stage_id,p_kind,p_claim,p_actor_id);select * into g from bizoveya_private.generation_stage_runs where id=p_stage_id;
 if exists(select 1 from bizoveya_private.meeting_turn_runs where profile_id=g.profile_id and (spending_state in('unknown','overrun') or spending_state='reserved' and created_at<statement_timestamp()-interval '90 seconds')) then raise exception 'bz_spending_unresolved';end if;
 limit_:=least((g.policy_snapshot->>'dailyLimitMicros')::bigint,(select (document->>'dailyBudgetCents')::bigint*10000 from bizoveya_private.model_profile_versions where profile_id=g.profile_id and version=g.profile_version));
 if coalesce((select sum(charged_micros) from bizoveya_private.spending_ledger where profile_id=g.profile_id and started_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)+coalesce((select sum(charged_micros) from bizoveya_private.generation_stage_runs where profile_id=g.profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)+coalesce((select sum(charged_micros) from bizoveya_private.meeting_turn_runs where profile_id=g.profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)>limit_ then raise exception 'bz_daily_budget';end if;return result_;end;$$;

create or replace function public.bz_admin_spending() returns jsonb language plpgsql security definer set search_path='' as $$begin perform bizoveya_private.require_admin();return jsonb_build_object(
 'policies',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('spentTodayMicros',coalesce((select sum(charged_micros) from bizoveya_private.spending_ledger where profile_id=p.profile_id and started_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)+coalesce((select sum(charged_micros) from bizoveya_private.generation_stage_runs where profile_id=p.profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0)+coalesce((select sum(charged_micros) from bizoveya_private.meeting_turn_runs where profile_id=p.profile_id and created_at>=date_trunc('day',statement_timestamp() at time zone 'UTC') at time zone 'UTC'),0),'blocked',exists(select 1 from bizoveya_private.spending_ledger where profile_id=p.profile_id and (state in('unknown','overrun') or state='reserved' and started_at<statement_timestamp()-interval '90 seconds')) or exists(select 1 from bizoveya_private.generation_stage_runs where profile_id=p.profile_id and (spending_state in('unknown','overrun') or spending_state='reserved' and created_at<statement_timestamp()-interval '90 seconds')) or exists(select 1 from bizoveya_private.meeting_turn_runs where profile_id=p.profile_id and (spending_state in('unknown','overrun') or spending_state='reserved' and created_at<statement_timestamp()-interval '90 seconds'))) order by p.updated_at desc) from bizoveya_private.spending_policies p),'[]'::jsonb),
 'runs',coalesce((select jsonb_agg(to_jsonb(z) order by z.started_at desc) from(select run_id,profile_id,policy_version,reserved_micros,charged_micros,state,input_tokens,output_tokens,started_at,finished_at,'model_test'::text run_kind,null::uuid generation_id,null::text stage_kind,null::uuid snapshot_id,null::integer turn_ordinal from bizoveya_private.spending_ledger union all select id,profile_id,policy_version,reserved_micros,charged_micros,spending_state,input_tokens,output_tokens,created_at,finished_at,'campaign_stage',generation_run_id,kind,null,null from bizoveya_private.generation_stage_runs union all select id,profile_id,policy_version,reserved_micros,charged_micros,spending_state,input_tokens,output_tokens,created_at,finished_at,'meeting_turn',null,null,snapshot_id,ordinal from bizoveya_private.meeting_turn_runs order by started_at desc limit 100)z),'[]'::jsonb),
 'events',coalesce((select jsonb_agg(to_jsonb(z) order by z.occurred_at desc) from(select id,run_id,action,amount_micros,actor_id,reason,occurred_at,'model_test'::text run_kind from bizoveya_private.spending_events union all select id,stage_id,action,amount_micros,actor_id,reason,occurred_at,'campaign_stage' from bizoveya_private.generation_spending_events union all select id,turn_id,action,amount_micros,actor_id,reason,occurred_at,'meeting_turn' from bizoveya_private.meeting_turn_spending_events order by occurred_at desc limit 100)z),'[]'::jsonb),
 'policyEvents',coalesce((select jsonb_agg(to_jsonb(z)) from(select * from bizoveya_private.spending_policy_events order by occurred_at desc limit 100)z),'[]'::jsonb));end;$$;

alter function public.bz_admin_reconcile_spending(uuid,text,bigint,text,boolean) set schema bizoveya_private;
alter function bizoveya_private.bz_admin_reconcile_spending(uuid,text,bigint,text,boolean) rename to reconcile_before_meeting_turns;
create function public.bz_admin_reconcile_spending(p_id uuid,p_expected_state text,p_amount_micros bigint,p_reason text,p_reviewed boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare m bizoveya_private.meeting_turn_runs%rowtype;begin
 if not exists(select 1 from bizoveya_private.meeting_turn_runs where id=p_id) then return bizoveya_private.reconcile_before_meeting_turns(p_id,p_expected_state,p_amount_micros,p_reason,p_reviewed);end if;
 perform bizoveya_private.require_admin();perform 1 from bizoveya_private.platform_admins where user_id=auth.uid() for share;if not found then raise exception 'bz_admin_forbidden' using errcode='42501';end if;
 if p_reviewed is distinct from true or p_amount_micros is null or p_amount_micros not between 0 and 1000000000 or length(btrim(coalesce(p_reason,''))) not between 10 and 300 or p_reason~'[\x01-\x1F]' then raise exception 'bz_invalid_spending';end if;
 perform pg_advisory_xact_lock(817030);select * into m from bizoveya_private.meeting_turn_runs where id=p_id for update;
 if m.spending_state is distinct from p_expected_state or not(m.spending_state in('unknown','overrun') or m.spending_state='reserved' and m.created_at<statement_timestamp()-interval '90 seconds') then raise exception 'bz_conflict';end if;
 update bizoveya_private.meeting_turn_runs set spending_state='reconciled',charged_micros=p_amount_micros,finished_at=coalesce(finished_at,clock_timestamp()),status=case when status='reserved' then 'failed' else status end,error_code=case when status='reserved' then 'reconciled_without_result' else error_code end where id=p_id;
 insert into bizoveya_private.meeting_turn_spending_events(turn_id,action,amount_micros,actor_id,reason) values(p_id,'reconciled',p_amount_micros,auth.uid(),btrim(p_reason));return public.bz_admin_spending();end;$$;

